/*
 * gl_solver_vectors.h - the reference vectors of the Python reference as C
 * data (HOST TESTS ONLY; never compiled for the target).
 *
 * The data are in tests/solver/gl_solver_vectors.c, GENERATED by
 * tools/gen_vectors.py from sim/results/reference_vectors.json; the layout
 * of that file is described in sim/results/REFERENCE_VECTORS.md.  Everything
 * here is double precision and independent of the solver's real type, so
 * that one table serves the double and the single build.
 *
 * GL_VEC_NAN stands for JSON null: not a number / not available.
 */
#ifndef GL_SOLVER_VECTORS_H
#define GL_SOLVER_VECTORS_H

#include <math.h>
#include <stdint.h>

#define GL_VEC_NAN ((double)NAN)

/** One placement (reference: Measurements). */
typedef struct {
    double f_px, baseline, h_cam, tilt[2];
    uint8_t tilt_reads, flag_found, flag_base_visible, flag_top_visible;
    double flag_bearing, flag_disparity, flag_low_elev, flag_top_elev;
    double stick_height_est, stick_height_rel_sigma;
    uint16_t n_horizon;      /**< horizon samples of this placement */
    uint32_t horizon_first;  /**< index of the first one in gl_vec_horizon_az / _elev */
    double grain_kappa, grain_azimuth, stimp_ft, user_distance;
} gl_vec_meas_t;

/** Expected outputs of an estimator case (the `expected` record). */
typedef struct {
    double patch[5], level_offsets[2], distance, distance_sigma, range_stereo, range_mono, bearing;
    uint8_t n_stations;
    double stations[4];
    double phi, aim_azimuth_device, v0, plays_like, break_m, break_cups, slope_pct;
    double fall_line_azimuth, dz_hole, cross_slope_sigma, confidence, a_r, grain[2], tilt_slopes[2];
    double fit_cost;
    uint8_t base_hidden, flag_missing, range_missing, poor_horizon, used_horizon, fit_converged;
    uint8_t aim_source, solve_status, fit_starts;
} gl_vec_expected_t;

/** One estimator case. */
typedef struct {
    uint16_t id;
    uint8_t group;           /**< 0 = estimator_cases, 1 = fallback_estimator_cases */
    const char *mode;
    const char *tag;         /**< what a fallback case exercises ("" in group 0) */
    uint8_t method;          /**< gl_solver_method_t */
    uint8_t use_grain;
    double past;
    double tol_miss, tol_pace, lm_tol; /**< tolerances the reference used */
    uint16_t lm_max_iter;
    uint8_t lm_max_iter_overridden;    /**< the case sets its own iteration limit */
    uint8_t n_drops;
    uint16_t first_meas;     /**< index of the drop at the ball in gl_vec_meas; the others follow */
    gl_vec_expected_t exp;
} gl_vec_est_case_t;

/** One aim-solver case: ball at the origin, hole at (distance, 0). */
typedef struct {
    uint16_t id;
    uint8_t group;           /**< 0 = solver_cases, 1 = fallback_solver_cases */
    const char *tag;
    double coeffs[5], distance, stimp_ft, a_r, grain[2], past, tol_miss, tol_pace;
    uint16_t max_rolls;
    uint8_t status, compare_values;
    double phi, v0, v_hole, miss, plays_like, aim_offset;
    int32_t n_rolls;         /**< trial rolls of the reference; -1 = not recorded (group 0) */
} gl_vec_sol_case_t;

/** One roll with the capture model (reference: simulate_putt). */
typedef struct {
    uint16_t id;
    const char *tag;
    double coeffs[5], z0, start[2], hole[2], phi, v0, a_r, grain[2], capture_exponent;
    uint8_t stop_on_capture, status, crossed, captured;
    int8_t side;
    double t_end, stop_xy[2], delta, speed_at_delta, lateral_at_line, speed_at_line;
    double lateral_miss, shortfall, path_length;
    uint32_t n_steps;
} gl_vec_roll_case_t;

extern const char gl_vec_source_sha256[];
extern const double gl_vec_const_g, gl_vec_const_hole_r, gl_vec_const_dt, gl_vec_const_t_max;
extern const unsigned gl_vec_const_step_budget_factor, gl_vec_const_max_rolls;

extern const double gl_vec_horizon_az[];
extern const double gl_vec_horizon_elev[];
extern const unsigned gl_vec_n_horizon;
extern const gl_vec_meas_t gl_vec_meas[];
extern const unsigned gl_vec_n_meas;
extern const gl_vec_est_case_t gl_vec_est[];
extern const unsigned gl_vec_n_est, gl_vec_n_est_original;
extern const gl_vec_sol_case_t gl_vec_sol[];
extern const unsigned gl_vec_n_sol, gl_vec_n_sol_original;
extern const gl_vec_roll_case_t gl_vec_roll[];
extern const unsigned gl_vec_n_roll;

#endif /* GL_SOLVER_VECTORS_H */
